#!/usr/bin/env bash
set -euo pipefail
# Build a visual+audio end-to-end reference MOV.
# Audio must first be generated by jls_generate_e2e_signal.py.
# PCM audio avoids adding a second lossy encoder delay before YouTube ingestion.
AUDIO="${1:-jls_e2e_reference.wav}"
OUT="${2:-jls_e2e_reference.mov}"
DURATION="${DURATION:-120}"

command -v ffmpeg >/dev/null || { echo "ffmpeg is required" >&2; exit 2; }

ffmpeg -hide_banner -loglevel error -y \
  -f lavfi -i "color=c=black:s=1280x720:r=60:d=${DURATION}" \
  -i "$AUDIO" \
  -vf "drawbox=x=0:y=0:w=iw:h=ih:color=white@1:t=fill:enable='lt(mod(t,1),0.10)',drawtext=text='JLS E2E REFERENCE':fontcolor=white:fontsize=52:x=(w-text_w)/2:y=h*0.42,drawtext=text='%{pts\\:hms}':fontcolor=white:fontsize=42:x=(w-text_w)/2:y=h*0.55" \
  -c:v libx264 -preset medium -crf 16 -pix_fmt yuv420p \
  -c:a pcm_s16le -ar 48000 -ac 2 -shortest "$OUT"

echo "Wrote $OUT"
echo "Integer-second click and white flash share the same nominal source timeline."
